#include <stddef.h>

void compress_string(const char *src, char *dest)
{
    if (!src || !dest) return;

    const char *prev = src;
    int count = 0;

    do {
        count++;
        if (*src != *prev) {
            *dest++ = *prev--;
            // write decimal count
            // Since run lengths are ≤ string length, we need a simple conversion
            // Collect digits in reverse order
            char tmp[12]; // enough for any 64-bit int as string
            int ti = 0;
            do {
                tmp[ti++] = (count % 10) + '0';
                count /= 10;
            } while(count > 0);
            // write in correct order
            while (ti--) *dest++ = tmp[ti];
            prev = src;
        }
    } while (*src++);

    *dest = '\0';
}

#include <stddef.h>

void compress_string(const char *src, char *dest)
{
    if (!src || !dest) return;

    const char *start = src;
    int count = 1;

    while (*src) {
        if (*(src + 1) != *src) {
            /* write the character */
            *dest++ = *src;
            /* write decimal count */
            char buf[12];
            int len = 0;
            do {
                buf[len++] = (count % 10) + '0';
                count /= 10;
            } while (count > 0);
            while (--len >= 0) *dest++ = buf[len];
        }
        src++;
    }

    *dest = '\0';
}
